/// <summary>
/// COC of CredManCreditControl
/// </summary>
[ExtensionOf(classstr(CredManCreditControl))]
final class METCredManCreditControl_Extension
{
}

Method.Source:
/// <summary>
/// Coc of isOrderHoldApplicable
/// </summary>
/// <returns>Boolean value</returns>
protected boolean isOrderHoldApplicable()
{
    boolean holdApplies = next isOrderHoldApplicable();
    holdApplies = this.METisOrderHoldApplicable();
    return holdApplies;
}

/// <summary>
/// Coc of METisOrderHoldApplicable
/// </summary>
/// <returns>Boolean value</returns>
protected boolean METisOrderHoldApplicable()
{
    boolean holdApplies;

    initOrderHoldControlItems = new Set(Types::Container);

    Array allOrderHoldChecks = CredManCreditControl::getAllOrderHoldChecks();
    int instanceCount = allOrderHoldChecks.lastIndex();

    SalesTable      salesTableLoc;
    for (int instanceIdx = 1; instanceIdx <= instanceCount; instanceIdx++)
    {
        CredManIOrderHoldCheck orderHoldCheck = allOrderHoldChecks.value(instanceIdx);
        CredManOrderHoldCheckContract credManOrderHoldCheckContract = this.getOrderHoldCheckContract();
        credManOrderHoldCheckContract.documentStatusCheck = CredManDocumentStatusCheck::METCreditCheck;
        orderHoldCheck.setOrderHoldCheckContract(credManOrderHoldCheckContract);

        if (orderHoldCheck.isApplicable())
        {
            Set orderHoldControlSubSet = orderHoldCheck.getOrderHoldControlItems();

            initOrderHoldControlItems = Set::union(initOrderHoldControlItems, orderHoldControlSubSet);

            salesTableLoc = credManOrderHoldCheckContract.salesTable;

            if (salesTableLoc.RecId)
            {
                salesTableLoc.selectForUpdate(true);
                salesTableLoc.skipDataMethods(true);

                salesTableLoc.METCreditCheckSalesOrder = true;
                salesTableLoc.update();
            }

            holdApplies = true;
        }
    }

    return holdApplies;
}

/// <summary>
/// Methot to get all order hold checks
/// </summary>
/// <returns>Array</returns>
public static Array getAllOrderHoldChecks()
{
    return SysPluginFactory::Instances(
        identifierStr(Dynamics.AX.Application),
        classStr(CredManOrderHoldCheck),
        new SysPluginMetadataCollection());
}
